/* ========================================================================== */
/* BFUSION Project Status Card                                               */
/* ========================================================================== */
.bfusion-root {
  width: 100%;
  height: 100%;
  overflow: auto;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  background-color: #FFFFFF;
  position: relative;
}
.bfusion-root *,
.bfusion-root *:before,
.bfusion-root *:after {
  box-sizing: border-box;
}
/* ========================================================================== */
/* Card Container                                                            */
/* ========================================================================== */
.bfusion-card-wrap {
  width: 100%;
  height: 100%;
  overflow-y: auto;
  padding: 16px 20px;
  display: block;
}
/* ========================================================================== */
/* Header                                                                    */
/* ========================================================================== */
.psc-header {
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid #eee;
}
.psc-header__title {
  font-size: 18px;
  font-weight: 700;
  color: #1a1a1a;
  line-height: 1.3;
  margin-bottom: 6px;
}
.psc-header__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 4px;
}
.psc-header__dates {
  font-size: 11px;
  color: #888;
  margin-top: 4px;
}
.psc-header__people {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 6px;
}
.psc-person {
  font-size: 11px;
  color: #555;
}
.psc-person__role {
  font-weight: 600;
  color: #999;
  text-transform: uppercase;
  font-size: 10px;
  letter-spacing: 0.3px;
  margin-right: 4px;
}
.psc-tag {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 500;
  background: #f3f4f6;
  color: #555;
}
.psc-tag--state {
  background: #e0e7ff;
  color: #3730a3;
}
.psc-tag--capex {
  font-weight: 600;
}
.psc-tag--green {
  background: #dcfce7;
  color: #166534;
}
.psc-tag--orange {
  background: #fff7ed;
  color: #9a3412;
}
/* ========================================================================== */
/* Sections                                                                  */
/* ========================================================================== */
.psc-section {
  margin-bottom: 16px;
}
.psc-section__title {
  font-size: 11px;
  font-weight: 600;
  color: #999;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 8px;
}
/* ========================================================================== */
/* RAG Health Strip                                                          */
/* ========================================================================== */
.psc-rag-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}
.psc-rag-item {
  display: flex;
  align-items: center;
  gap: 6px;
  background: #fafafa;
  border-radius: 6px;
  padding: 6px 10px;
  flex: 1 1 auto;
  min-width: 120px;
}
.psc-rag-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  flex-shrink: 0;
}
.psc-rag-label {
  font-size: 12px;
  font-weight: 600;
  color: #333;
  flex-shrink: 0;
}
.psc-rag-status {
  font-size: 11px;
  color: #777;
  flex: 1;
}
.psc-rag-trend {
  font-size: 12px;
  font-weight: 700;
  flex-shrink: 0;
}
/* ========================================================================== */
/* KPI Boxes                                                                 */
/* ========================================================================== */
.psc-kpi-row {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.psc-kpi {
  flex: 1 1 0;
  min-width: 70px;
  background: #fafafa;
  border-radius: 6px;
  padding: 8px 12px;
  text-align: center;
}
.psc-kpi__value {
  font-size: 20px;
  font-weight: 700;
  line-height: 1.2;
}
.psc-kpi__label {
  font-size: 10px;
  color: #888;
  margin-top: 2px;
}
/* ========================================================================== */
/* Task Bar                                                                  */
/* ========================================================================== */
.psc-task-bar {
  display: flex;
  height: 8px;
  border-radius: 4px;
  overflow: hidden;
  margin-bottom: 8px;
  background: #f3f4f6;
}
.psc-task-seg {
  height: 100%;
  transition: width 0.3s ease;
}
/* ========================================================================== */
/* Budget Gauge                                                              */
/* ========================================================================== */
.psc-gauge {
  margin-bottom: 8px;
}
.psc-gauge__track {
  position: relative;
  height: 10px;
  border-radius: 5px;
  background: #f3f4f6;
  overflow: visible;
}
.psc-gauge__fill {
  height: 100%;
  border-radius: 5px;
  transition: width 0.3s ease;
}
.psc-gauge__marker {
  position: absolute;
  top: -3px;
  width: 3px;
  height: 16px;
  background: #333;
  border-radius: 1px;
  transform: translateX(-1px);
}
/* ========================================================================== */
/* Comments                                                                  */
/* ========================================================================== */
.psc-comment {
  background: #fafafa;
  border-radius: 6px;
  padding: 8px 12px;
  margin-bottom: 6px;
}
.psc-comment__label {
  font-size: 11px;
  font-weight: 600;
  color: #555;
  margin-bottom: 4px;
}
.psc-comment__body {
  font-size: 12px;
  color: #444;
  line-height: 1.5;
}
.psc-comment__body p {
  margin: 0 0 4px 0;
}
/* ========================================================================== */
/* Landing Page                                                              */
/* ========================================================================== */
.bfusion-landing-wrap {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background-color: #FFFFFF;
}
.bfusion-landing {
  display: flex;
  flex-direction: column;
  align-items: center;
  max-width: 420px;
  padding: 20px;
  box-sizing: border-box;
  text-align: center;
}
.bfusion-landing__logo-container {
  width: 130px;
  height: 84px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #FF5500;
  border-radius: 12px;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.08);
  margin-bottom: 24px;
  overflow: hidden;
}
.bfusion-landing__logo {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.bfusion-landing__text-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}
.bfusion-landing__title {
  font-size: 15px;
  font-weight: 600;
  color: #242424;
  margin: 0 0 14px 0;
  padding: 0;
  line-height: 1.2;
}
.bfusion-landing__description {
  font-size: 11.5px;
  font-weight: 400;
  color: #666666;
  margin: 0;
  padding: 0;
  line-height: 1.5;
}
.bfusion-landing__description strong {
  font-weight: 600;
  color: #444444;
}
.bfusion-landing__separator {
  width: 60%;
  height: 1px;
  background-color: #EAEAEA;
  margin: 20px 0;
}
.bfusion-landing__metadata {
  font-size: 10.5px;
  color: #8C8C8C;
  margin-bottom: 4px;
  font-weight: 400;
  line-height: 1.4;
}
.bfusion-landing__metadata strong {
  font-weight: 600;
  color: #707070;
}
/* ========================================================================== */
/* License Badge & Watermark                                                   */
/* ========================================================================== */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: rgba(5, 150, 105, 0.08);
  border: 1px solid rgba(5, 150, 105, 0.25);
  color: #059669;
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
.bfusion-watermark {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 15;
  pointer-events: none;
  display: flex;
  align-items: center;
  justify-content: center;
  background: repeating-linear-gradient(-45deg, transparent, transparent 120px, rgba(220, 38, 38, 0.03) 120px, rgba(220, 38, 38, 0.03) 122px);
}
.bfusion-watermark__content {
  text-align: center;
  opacity: 0.18;
  user-select: none;
  transform: rotate(-18deg);
}
.bfusion-watermark__title {
  font-size: 56px;
  font-weight: 900;
  color: #DC2626;
  letter-spacing: 12px;
  line-height: 1;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__subtitle {
  font-size: 16px;
  font-weight: 600;
  color: #DC2626;
  margin-top: 6px;
  letter-spacing: 3px;
  text-transform: uppercase;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__link {
  font-size: 11px;
  color: #9CA3AF;
  margin-top: 12px;
  font-family: "Segoe UI", sans-serif;
}
/* ========================================================================== */
/* Empty Data State (cross-filter excluded everything)                        */
/* ========================================================================== */
.bfusion-empty {
  display: flex;
  width: 100%;
  height: 100%;
  align-items: center;
  justify-content: center;
  padding: 20px 24px 28px 24px;
  box-sizing: border-box;
}
.bfusion-empty__message {
  font-size: 12px;
  color: #94a3b8;
  font-weight: 400;
  text-align: center;
  letter-spacing: 0.2px;
}
